pub fn characterAttrSlot(attr_name: []const u8) ?usize {
    if (std.mem.eql(u8, attr_name, "position")) {
        return 0;
    }
    if (std.mem.eql(u8, attr_name, "normal")) {
        return 1;
    }
    if (std.mem.eql(u8, attr_name, "inst_x")) {
        return 2;
    }
    if (std.mem.eql(u8, attr_name, "inst_y")) {
        return 3;
    }
    if (std.mem.eql(u8, attr_name, "inst_z")) {
        return 4;
    }
    if (std.mem.eql(u8, attr_name, "inst_color")) {
        return 5;
    }
    return null;
}
pub fn characterTextureSlot(tex_name: []const u8) ?usize {
    _ = tex_name;
    return null;
}
pub fn characterSamplerSlot(smp_name: []const u8) ?usize {
    _ = smp_name;
    return null;
}
pub fn characterUniformBlockSlot(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return 0;
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        return 1;
    }
    return null;
}
pub fn characterUniformBlockSize(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return @sizeOf(VsParams);
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        return @sizeOf(FsParams);
    }
    return null;
}
pub fn characterUniformOffset(ub_name: []const u8, u_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "view_projection")) {
            return 0;
        }
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        if (std.mem.eql(u8, u_name, "light_direction")) {
            return 0;
        }
    }
    return null;
}
pub fn characterUniformDesc(ub_name: []const u8, u_name: []const u8) ?sg.GlslShaderUniform {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "view_projection")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "view_projection";
            return desc;
        }
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        if (std.mem.eql(u8, u_name, "light_direction")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT3;
            desc.array_count = 0;
            desc.glsl_name = "light_direction";
            return desc;
        }
    }
    return null;
}
pub fn characterStorageBufferSlot(sbuf_name: []const u8) ?usize {
    _ = sbuf_name;
    return null;
}
pub fn characterStorageImageSlot(simg_name: []const u8) ?usize {
    _ = simg_name;
    return null;
